sp_widget.css:
.section-header {
  font-size: 16px;
  font-weight: 700;
  color: $brand-primary;
  border-bottom: 2px solid $brand-secondary;
  padding-bottom: 5px;
  margin-top: 20px;
  margin-bottom: 15px;
}
.field-value {
  font-size: 14px;
  color: #333;
  margin-bottom: 5px;
  word-break: break-word;
}
label {
  color: #777;
  font-size: 11px;
  text-transform: uppercase;
  display: block;
  margin-bottom: 2px;
}
.pre-line { white-space: pre-line; }
.ai-summary {
  background-color: #f9f9f9;
  padding: 10px;
  border-left: 3px solid $brand-info;
  font-style: italic;
}
.mt-20 { margin-top: 20px; }

sp_widget.script:
(function() {
  var sys_id = $sp.getParameter('sys_id') || options.sys_id;
  if (!sys_id) return;
  var gr = new GlideRecordSecure('x_1603911_casepo_0_legal_case');
  if (gr.get(sys_id)) {
      data.isValid = true;
      data.case = {
          sys_id: gr.getUniqueValue(),
          number: gr.getValue('number'),
          short_description: gr.getDisplayValue('short_description'),
          description: gr.getDisplayValue('description'),
          state: gr.getDisplayValue('state'),
          priority: gr.getDisplayValue('priority'), // Standard Priority
          assigned_to: gr.getDisplayValue('assigned_to'),
          requestor: gr.getDisplayValue('legal_requestor'),

          // AI Fields
          ai_priority: gr.getDisplayValue('ai_priority'),
          ai_category: gr.getDisplayValue('ai_category'),
          ai_confidence: gr.getDisplayValue('ai_confidence'),
          ai_summary: gr.getDisplayValue('case_summary') // Mapped to 'case_summary' field
      };

      // Fetch Standard Attachments
      data.attachments = [];
      var attCheck = new GlideRecordSecure('sys_attachment');
      attCheck.addQuery('table_sys_id', sys_id);
      attCheck.query();
      while(attCheck.next()) {
        data.attachments.push({
          name: attCheck.getValue('file_name'),
          size: attCheck.getValue('size_bytes') + ' bytes',
          sys_id: attCheck.getUniqueValue()
        });
      }
  }
  // Fetch Custom Case Documents
  data.documents = [];
  var docGR = new GlideRecordSecure('x_1603911_casepo_0_case_document');
  docGR.addQuery('parent_case', sys_id);
  docGR.orderByDesc('uploaded_on');
  docGR.query();
  while (docGR.next()) {
    data.documents.push({
      sys_id: docGR.getUniqueValue(),
      version: docGR.getValue('document_version'),
      is_latest: docGR.getValue('is_latest_version') == '1',
      uploaded_on: docGR.getDisplayValue('uploaded_on'),
      uploaded_by: docGR.getDisplayValue('uploaded_by'),
      // Assuming name/filename is implicitly handled or generic
      filename: "Case Document" 
    });
  }
})();
